 w.document.open();w.document.write('<!doctype html><html lang="bn"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NABABI Attendance</title><style>*{box-sizing:border-box}body{margin:0;padding:24px;background:#f1f5f1;color:#183c2c;font-family:"Noto Sans Bengali","Hind Siliguri",Arial,sans-serif}.sheet{max-width:1000px;margin:auto;background:#fff;border:1px solid #d7bd75;border-radius:18px;overflow:hidden}.head{padding:25px;text-align:center;background:linear-gradient(120deg,#103b2b,#246044);color:#fff}.head img{display:block;max-width:145px;max-height:70px;object-fit:contain;margin:0 auto 8px}.head h1{color:#f0d58d;margin:6px}.profile{display:flex;align-items:center;gap:15px;padding:20px 24px}.profile img{width:74px;height:74px;object-fit:cover;border-radius:50%;border:3px solid #d6b66a}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:0 24px 20px}.card{padding:13px;border-radius:12px;text-align:center;background:#e4f3e8;color:#17623a}.card.red{background:#fde8e6;color:#a72e28}.card.gold{background:#fff1d1;color:#8a6216}.card b{display:block;font-size:21px}.range{margin:0 24px 16px;padding:10px 14px;background:#f8f1df;border-left:4px solid #c6a353}.table{padding:0 24px 24px}table{width:100%;border-collapse:collapse;font-size:12px}th{padding:11px;text-align:left;background:#16432f;color:#f9e7b6}td{padding:10px;border-bottom:1px solid #e1e8e1}tr:nth-child(even) td{background:#f2f7f3}.foot{padding:17px;text-align:center;background:#103b2b;color:#f0d58d;font-weight:bold}@media print{body{padding:0;background:#fff}.sheet{border:0;border-radius:0}.head,.foot,th,.card,.range,tr:nth-child(even) td{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media(max-width:650px){.cards{grid-template-columns:repeat(2,1fr)}body{padding:8px}table{font-size:9px}td,th{padding:5px}} .logo-setting-preview{display:grid;gap:10px;min-width:180px;max-width:280px}.logo-setting-url{max-width:260px;overflow-wrap:anywhere;font-size:12px;line-height:1.5}.logo-setting-preview img{display:block;width:120px;height:64px;max-width:100%;object-fit:contain;padding:0;border:0;border-radius:0;background:transparent}.logo-setting-preview img[hidden]{display:none}</style><body><main class="sheet"><header class="head">'+(attendanceLogoUrl?'<img src="'+esc(attendanceLogoUrl)+'" alt="Nababi">':'<h1>♛ NABABI RISTORANTE</h1>')+'<h1>স্টাফ উপস্থিতির প্রতিবেদন</h1><p>সাপ্তাহিক / মাসিক রিপোর্ট</p></header><section class="profile">'+(photo?'<img src="'+esc(photo)+'" alt="">':'')+'<div><h2>'+esc(isPerson?selectedAttendanceStaff:'সকল স্টাফ')+'</h2><p>'+esc(attendanceStart||'শেষ ৭ দিন')+' — '+esc(attendanceEnd||attendanceDateValue(new Date()))+'</p></div></section><section class="cards"><div class="card"><b>'+data.length+'</b><span>মোট রেকর্ড</span></div><div class="card"><b>'+complete.length+'</b><span>সম্পূর্ণ শিফট</span></div><div class="card red"><b>'+missing.length+'</b><span>চেক-আউট বাকি</span></div><div class="card gold"><b>'+esc(attendanceHours(minutes))+'</b><span>মোট ডিউটি</span></div></section><p class="range">রিপোর্টের সময়কাল: '+esc(attendanceStart||'শেষ ৭ দিন')+' থেকে '+esc(attendanceEnd||attendanceDateValue(new Date()))+'</p><div class="table"><table><thead><tr><th>স্টাফের নাম</th><th>তারিখ</th><th>শিফট</th><th>চেক-ইন</th><th>চেক-আউট</th><th>ডিউটি</th><th>অবস্থা</th></tr></thead><tbody>'+tr+'</tbody></table></div><footer class="foot">ধন্যবাদ · NABABI RISTORANTE পরিবারের পক্ষ থেকে</footer></main><script>window.addEventListener("load",()=>setTimeout(()=>window.print(),700));<\/script></body></html>');w.document.close();
