async function createAttendanceStaff(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const form=e.target,fd=new FormData(form),status=$('#attendanceStaffStatus'),file=fd.get('photo'),pin=String(fd.get('pin')||'');if(!/^[0-9]{4}$/.test(pin))throw new Error('PIN must contain exactly four digits.');if(!file||!file.size)throw new Error('Select a staff photo.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Use JPG, PNG or WebP up to 8 MB.');let path=null;try{const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',bucket=cfg.STORAGE_BUCKET||'nababi-media';const up=await db.storage.from(bucket).upload('staff/'+Date.now()+'-'+Math.random().toString(36).slice(2)+'.'+ext,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(up.error)throw up.error;path=up.data.path;const url=db.storage.from(bucket).getPublicUrl(path).data.publicUrl;const r=await db.rpc('admin_create_staff_pin_account',{p_full_name:String(fd.get('full_name')||'').trim(),p_photo_url:url,p_pin:pin});if(r.error)throw r.error;if(!r.data?.ok)throw new Error(r.data?.message||'Staff account creation failed.');form.reset();status.textContent=r.data.message||'Attendance account created.';await render('staff')}catch(err){if(path)await db.storage.from(cfg.STORAGE_BUCKET||'nababi-media').remove([path]);status.textContent=err.message;throw err}}
async function publishStaffAnnouncement(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const form=e.target,fd=new FormData(form),title=String(fd.get('title')||'').trim(),message=String(fd.get('message')||'').trim(),status=$('#staffAnnouncementStatus'),button=form.querySelector('[type="submit"]');if(!title||!message)throw new Error('Title and message are required.');const startDate=String(fd.get('starts_date')||''),startTime=String(fd.get('starts_time')||'00:00'),endDate=String(fd.get('ends_date')||''),endTime=String(fd.get('ends_time')||'23:59');const startsAt=startDate?new Date(startDate+'T'+startTime):new Date();const endsAt=endDate?new Date(endDate+'T'+endTime):null;if(Number.isNaN(startsAt.getTime())||(endsAt&&Number.isNaN(endsAt.getTime())))throw new Error('Please choose a valid date and time.');if(endsAt&&endsAt<=startsAt)throw new Error('End date and time must be after the start date and time.');if(button)button.disabled=true;if(status)status.textContent='Saving announcement…';try{const payload={title,message,starts_at:startsAt.toISOString(),ends_at:endsAt?endsAt.toISOString():null,is_active:true};const r=await db.from('staff_announcements').insert(payload);if(r.error)throw r.error;await loadStaffAnnouncements();form.reset();if(status)status.textContent='Announcement saved successfully.';}catch(err){if(status)status.textContent='Save failed: '+(err.message||'Unknown error');throw err;}finally{if(button)button.disabled=false}}

async function secretPage(){const [history]=await Promise.all([db.from('coupon_redemptions').select('coupon_code,discount_percent,redeemed_by_name,redeemed_at').order('redeemed_at',{ascending:false}).limit(100)]);if(history.error)throw history.error;return '<section class="panel secret-coupon-panel"><div class="secret-coupon-heading"><div><p class="eyebrow">NABABI · CUSTOMER REWARDS</p><h2>🎁 Secret Coupon Box</h2><p class="help">Enter the code shown by the customer. Each valid coupon can be redeemed only once.</p></div><span class="secret-coupon-mark" aria-hidden="true">♛</span></div><form id="redeemSecretForm" class="admin-form"><label class="field">Customer coupon code<input name="code" inputmode="numeric" autocomplete="off" pattern="[0-9]{5,9}" minlength="5" maxlength="9" placeholder="Enter 5–9 digit code" required></label><button class="gold-button" type="submit">Verify &amp; Redeem</button><p id="redeemSecretStatus" class="message secret-coupon-result" role="status" aria-live="polite"></p></form></section>'+(role==='admin'?'<section class="panel"><h2>Generate customer coupon</h2><button id="generateSecretCoupon" class="gold-button" type="button">Generate coupon</button><div id="generatedCoupon" class="message"></div></section>':'')+'<section class="panel"><h2>Redemption history</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Coupon</th><th>Discount</th><th>Collected by</th><th>Date</th></tr></thead><tbody>'+(history.data||[]).map(x=>'<tr><td>'+esc(x.coupon_code)+'</td><td>'+esc(x.discount_percent)+'%</td><td>'+esc(x.redeemed_by_name||'Staff')+'</td><td>'+esc(x.redeemed_at?new Date(x.redeemed_at).toLocaleString():'')+'</td></tr>').join('')+'</tbody></table></div></section>'}
function launchSecretFireworks(){document.querySelectorAll('.secret-fireworks').forEach(x=>x.remove());const layer=document.createElement('div');layer.className='secret-fireworks';layer.setAttribute('aria-hidden','true');for(let burst=0;burst<7;burst++){const group=document.createElement('div');group.className='secret-firework-burst';group.style.left=(10+burst*13)+'%';group.style.top=(18+(burst%3)*24)+'%';group.style.setProperty('--burst-delay',(burst*110)+'ms');for(let i=0;i<24;i++){const spark=document.createElement('i');spark.style.setProperty('--angle',(i*15)+'deg');spark.style.setProperty('--distance',(105+(i%5)*27)+'px');spark.style.setProperty('--hue',String((i*19+burst*53)%360));group.appendChild(spark)}layer.appendChild(group)}document.body.appendChild(layer);window.setTimeout(()=>layer.remove(),3200)}
function showSecretResult(state,message,discount){const success=state==='success';$('#pageTitle').textContent=success?'Coupon redeemed':'Coupon not accepted';$('#content').innerHTML='<section class="secret-result-screen '+(success?'is-success':'is-error')+'" role="status" aria-live="assertive"><div class="secret-result-card"><div class="secret-result-icon" aria-hidden="true">'+(success?'🎉':'✕')+'</div><p class="eyebrow">'+(success?'NABABI · CUSTOMER REWARDS':'NABABI · COUPON VERIFICATION')+'</p><h2>'+(success?'Congratulations!':'Coupon not valid')+'</h2><p class="secret-result-message">'+esc(message)+'</p>'+(success?'<div class="secret-result-discount">'+esc(discount||'')+'% <span>DISCOUNT</span></div>':'<p class="secret-result-hint">Please check the customer code and try again.</p>')+'<button class="gold-button" type="button" data-module="secret">'+(success?'Back to Secret Coupon Box':'Try another code')+'</button></div></section>';if(success)launchSecretFireworks();}
async function redeemSecretCoupon(e){e.preventDefault();const form=e.target,code=String(new FormData(form).get('code')||'').trim(),button=form.querySelector('[type="submit"]');button.disabled=true;try{if(!/^[0-9]{5,9}$/.test(code))throw new Error('Invalid code. Enter the 5–9 digit customer code.');const r=await db.rpc('redeem_nababi_coupon',{p_code:code});if(r.error)throw r.error;if(!r.data?.success)throw new Error(r.data?.message||'Invalid or already redeemed coupon.');await recordStaffActivity('Redeemed','Module: Secret Coupon Box — '+code);showSecretResult('success','Your coupon has been verified and redeemed successfully.',r.data.discount_percent||'');}catch(err){showSecretResult('error',err.message||'Invalid coupon code. Please check and try again.')}finally{button.disabled=false}}
async function generateSecretCoupon(){if(role!=='admin')throw new Error('Admin only.');const out=$('#generatedCoupon'),r=await db.rpc('generate_nababi_coupon');if(r.error)throw r.error;if(!r.data?.success)throw new Error(r.data?.message||'Coupon generation failed.');out.textContent='Generated code: '+r.data.code+' · '+r.data.discount_percent+'% discount';}
async function discountPage(){const r=await db.rpc('get_nababi_coupon_offer');if(r.error)throw r.error;const d=r.data||{};return '<section class="panel"><h2>Customer Discount Offer</h2><p class="help">Manage the offer shown on the public website. Existing issued coupons keep their own expiry.</p><form id="discountOfferForm" class="admin-form">'+selectField('Discount percent','discount_percent',['10','15','20','25','30'].map(x=>'<option value="'+x+'" '+(String(d.discount_percent||10)===x?'selected':'')+'>'+x+'%</option>').join(''))+field('Maximum coupons (optional)','max_coupons','number','min="1" step="1" value="'+(d.max_coupons??'')+'"')+field('Starts at','starts_at','datetime-local','required value="'+(d.starts_at?new Date(new Date(d.starts_at).getTime()-new Date(d.starts_at).getTimezoneOffset()*60000).toISOString().slice(0,16):'')+'"')+field('Ends at','ends_at','datetime-local','required value="'+(d.ends_at?new Date(new Date(d.ends_at).getTime()-new Date(d.ends_at).getTimezoneOffset()*60000).toISOString().slice(0,16):'')+'"')+'<label class="check-label"><input type="checkbox" name="is_enabled" '+(d.is_enabled?'checked':'')+'> Enable offer</label><button class="gold-button" type="submit">Save offer</button><p id="discountStatus" class="message"></p></form><p class="help">Current: '+(d.is_active?'ACTIVE':'INACTIVE')+' · Issued: '+esc(d.issued_count||0)+' / '+esc(d.max_coupons??'Unlimited')+'</p></section>'}
async function saveDiscountOffer(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const fd=new FormData(e.target),start=fd.get('starts_at'),end=fd.get('ends_at'),max=fd.get('max_coupons');if(!start||!end||new Date(end)<=new Date(start))throw new Error('Check the offer start and end dates.');if(max&&(!Number.isInteger(Number(max))||Number(max)<1))throw new Error('Maximum coupons must be a positive whole number.');const r=await db.rpc('save_nababi_coupon_offer',{p_discount_percent:Number(fd.get('discount_percent')),p_starts_at:new Date(start).toISOString(),p_ends_at:new Date(end).toISOString(),p_is_enabled:$('#discountOfferForm').elements.is_enabled.checked,p_max_coupons:max?Number(max):null});if(r.error)throw r.error;if(!r.data?.success)throw new Error(r.data?.message||'Offer save failed.');await render('discount')}
async function activityPage(){
 const [{data:logs,error:logError},{data:staff,error:staffError}]=await Promise.all([
  db.from('staff_activity_logs').select('*').limit(200),
  db.from('staff').select('id,auth_user_id,full_name,photo_url')
 ]);
 if(logError)throw logError;
 if(staffError)throw staffError;
 const people=staff||[];
 const byId=new Map(people.map(p=>[String(p.id),p]));
 const byAuth=new Map(people.filter(p=>p.auth_user_id).map(p=>[String(p.auth_user_id),p]));
 const byName=new Map(people.map(p=>[String(p.full_name||'').trim().toLocaleLowerCase(),p]));
 const rows=(logs||[]).slice().sort((a,b)=>new Date(b.created_at||b.performed_at||b.timestamp||0)-new Date(a.created_at||a.performed_at||a.timestamp||0));
 const value=(row,keys)=>{for(const key of keys){const v=row[key];if(v!==undefined&&v!==null&&v!=='')return typeof v==='object'?JSON.stringify(v):String(v)}return ''};
 const escAttr=v=>esc(v).replace(/\`/g,'&#96;');
 const avatar=(person,name)=>person?.photo_url?'<img src="'+escAttr(person.photo_url)+'" alt="'+escAttr(name)+'" style="width:48px;height:48px;object-fit:cover;border-radius:50%;flex:0 0 auto">':'<div aria-label="Staff photo unavailable" style="width:48px;height:48px;border-radius:50%;background:#e8dfc9;color:#334;display:grid;place-items:center;font-size:20px;flex:0 0 auto">♟</div>';
 return '<section class="panel"><h2>'+t('activity')+'</h2><p class="help">Recent staff actions. Staff ID is kept internal and is not displayed.</p>'+
 (rows.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Staff</th><th>Activity</th><th>Module</th><th>Date &amp; Time</th></tr></thead><tbody>'+
 rows.map(row=>{
  const person=byId.get(String(row.staff_id||row.staffId||''))||byAuth.get(String(row.auth_user_id||row.user_id||''))||byName.get(String(row.staff_name||row.full_name||row.actor_name||'').trim().toLocaleLowerCase());
  const name=person?.full_name||value(row,['staff_name','full_name','actor_name','user_name'])||'Staff';
  const action=value(row,['action','activity','event','description','action_name'])||'Activity recorded';
  const detail=value(row,['details']);const moduleMatch=detail.match(/Module:\s*([^—\n]+)/i);const module=moduleMatch?moduleMatch[1].trim():'—';
  const stamp=value(row,['created_at','performed_at','timestamp','activity_at','logged_at']);
  const date=stamp&&!Number.isNaN(new Date(stamp).getTime())?new Date(stamp).toLocaleString():(stamp||'—');
  return '<tr><td><span style="display:inline-flex;align-items:center;gap:10px">'+avatar(person,name)+'<b>'+esc(name)+'</b></span></td><td>'+esc(action)+'</td><td>'+esc(module)+'</td><td>'+esc(date)+'</td></tr>';
 }).join('')+'</tbody></table></div>':'<div class="empty">'+t('empty')+'</div>')+'</section>';
}
async function hoursPage(){const r=await db.from('opening_hours').select('id,day_of_week,day_name,is_closed,opens_at,closes_at').order('day_of_week');if(r.error)throw r.error;return '<section class="panel"><h2>Opening hours</h2><form id="hoursForm">'+(r.data||[]).map(x=>'<div class="record-row"><b>'+esc(x.day_name)+'</b><label class="check-label"><input type="checkbox" name="closed_'+esc(x.id)+'" '+(x.is_closed?'checked':'')+'> Closed</label><label class="field">Opens<input type="time" name="open_'+esc(x.id)+'" value="'+esc(x.opens_at?String(x.opens_at).slice(0,5):'')+'"></label><label class="field">Closes<input type="time" name="close_'+esc(x.id)+'" value="'+esc(x.closes_at?String(x.closes_at).slice(0,5):'')+'"></label></div>').join('')+'<button class="gold-button" type="submit">Save opening hours</button><p id="hoursStatus" class="message"></p></form></section>'}
async function saveHours(e){e.preventDefault();const form=e.target,status=$('#hoursStatus'),ids=[...form.querySelectorAll('[name^="closed_"]')].map(x=>x.name.slice(7));for(const id of ids){const closed=form.elements['closed_'+id].checked,open=form.elements['open_'+id].value,close=form.elements['close_'+id].value;if(!closed&&(!open||!close||open>=close))throw new Error('Enter valid opening and closing times or mark the day closed.');const r=await db.from('opening_hours').update({is_closed:closed,opens_at:closed?null:open,closes_at:closed?null:close,updated_at:new Date().toISOString()}).eq('id',id).select('id').maybeSingle();if(r.error)throw r.error;if(!r.data)throw new Error('No opening-hours row was updated. Check Supabase RLS.')}status.textContent='Opening hours saved.'}

function staffQrCodePage(){const currentUrl=new URL('/staff-qr.html',location.origin).href;return '<section class="attendance-hero"><div><p class="eyebrow">NABABI RISTORANTE</p><h2>Staff Attendance QR</h2><p>Edit the QR destination, preview it and download a PNG copy.</p></div><div class="attendance-hero-icon">▣</div></section><section class="panel staff-qr-manager"><h2>QR Code Editor</h2><label class="field" for="staffQrValue">QR destination URL<input id="staffQrValue" type="url" value="'+esc(currentUrl)+'" autocomplete="url" spellcheck="false"></label><div class="staff-qr-actions"><button id="resetStaffQr" class="secondary-button" type="button">Use current attendance link</button><button id="downloadStaffQr" class="gold-button" type="button">Download QR · PNG</button></div><div id="staffQrPreview" class="staff-qr-preview" aria-label="QR code preview"></div><p id="staffQrStatus" class="attendance-footnote" role="status" aria-live="polite">Default link: '+esc(currentUrl)+'</p><p class="attendance-footnote">Important: changing this URL changes only the QR image you download. To keep Staff Check-in/Check-out working, use the current attendance link shown above. This editor does not change attendance records or database settings.</p></section>'}
function initStaffQrCode(){const input=$('#staffQrValue'),preview=$('#staffQrPreview'),status=$('#staffQrStatus'),reset=$('#resetStaffQr'),download=$('#downloadStaffQr');if(!input||!preview||!status||!reset||!download)return;let qr=null;const draw=()=>{preview.replaceChildren();const value=input.value.trim();if(!value){status.textContent='Enter a URL to create the QR code.';qr=null;return}let url;try{url=new URL(value);if(!['https:','http:'].includes(url.protocol))throw new Error('Only HTTP or HTTPS links are supported.')}catch(e){status.textContent=e.message==='Only HTTP or HTTPS links are supported.'?e.message:'Enter a valid URL.';qr=null;return}if(typeof QRCode!=='function'){status.textContent='QR generator could not be loaded. Check your internet connection and reload this page.';qr=null;return}qr=new QRCode(preview,{text:url.href,width:280,height:280,colorDark:'#102d24',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H});status.textContent='QR preview ready · '+url.href};input.addEventListener('input',draw);reset.addEventListener('click',()=>{input.value=new URL('/staff-qr.html',location.origin).href;draw()});download.addEventListener('click',()=>{if(!qr){draw();if(!qr)return}const canvas=preview.querySelector('canvas'),image=preview.querySelector('img');let dataUrl='';try{if(canvas)dataUrl=canvas.toDataURL('image/png');else if(image&&image.src.startsWith('data:image/'))dataUrl=image.src}catch(e){status.textContent='Could not export the QR image. Please reload and try again.';return}if(!dataUrl){status.textContent='QR image is not ready yet. Please try again.';return}try{const base64=dataUrl.split(',')[1],binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const blob=new Blob([bytes],{type:'image/png'}),objectUrl=URL.createObjectURL(blob),link=document.createElement('a');link.href=objectUrl;link.download='nababi-staff-attendance-qr.png';document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(objectUrl),30000);status.textContent='PNG download started.'}catch(e){const link=document.createElement('a');link.href=dataUrl;link.download='nababi-staff-attendance-qr.png';document.body.appendChild(link);link.click();link.remove();status.textContent='PNG ready. If it opens as an image, use Share → Save to Files.'}});draw()}


async function bookingsPageV2(){
 if(!can('bookings'))throw new Error('Non hai i permessi per gestire le prenotazioni.');
 const q=await db.from('bookings').select('*').order('created_at',{ascending:false}).limit(100);if(q.error)throw q.error;
 const rows=q.data||[];let tableNames=new Map();try{const tr=await db.from('booking_floor_tables').select('id,table_code');if(!tr.error)tableNames=new Map((tr.data||[]).map(t=>[String(t.id),t.table_code]));}catch(e){console.warn('Booking table labels unavailable:',e.message)}const count=s=>rows.filter(r=>String(r.status||'pending').toLowerCase()===s).length;
 return '<section class="panel booking-admin-panel"><div class="booking-admin-head"><div><p class="eyebrow">NABABI RISTORANTE</p><h2>Table Bookings</h2><p class="booking-help">সম্পূর্ণ বুকিং তথ্য, তারিখ ও স্ট্যাটাস ফিল্টার এবং গ্রাহককে মেসেজ পাঠানোর অপশন।</p></div><button class="secondary-button" data-refresh-bookings>↻ Refresh</button></div><div class="booking-tools"><label class="field">Booking date<input id="bookingCalendarDate" type="date" aria-label="Filter bookings by date"></label><button class="booking-stat" data-booking-filter="all"><b>'+rows.length+'</b><span>All</span></button><button class="booking-stat pending" data-booking-filter="pending"><b>'+count('pending')+'</b><span>Pending</span></button><button class="booking-stat confirmed" data-booking-filter="confirmed"><b>'+count('confirmed')+'</b><span>Confirmed</span></button><button class="booking-stat rejected" data-booking-filter="rejected"><b>'+count('rejected')+'</b><span>Rejected</span></button><button class="booking-stat cancelled" data-booking-filter="cancelled"><b>'+count('cancelled')+'</b><span>Cancelled</span></button></div><p id="bookingCalendarNote" class="booking-help"></p><div class="table-wrap"><table class="data-table booking-table"><thead><tr><th>Customer / Code</th><th>Contact</th><th>Date / Time</th><th>Guests</th><th>Table</th><th>Status</th><th>Actions</th></tr></thead><tbody id="bookingCalendarRows">'+rows.map(r=>{const tableName=r.table_number??r.table_name??tableNames.get(String(r.selected_table_id||''))??'—',st=String(r.status||'pending').toLowerCase(),name=r.full_name||r.name||r.customer_name||'—',code=r.booking_code||r.confirmation_code||'—';return '<tr data-booking-date="'+esc(String(r.booking_date||'').slice(0,10))+'" data-booking-status="'+esc(st)+'"><td><b>'+esc(name)+'</b><br><small>'+esc(code)+'</small>'+(r.notes?'<br><small>'+esc(r.notes)+'</small>':'')+'</td><td>'+esc(r.phone||'—')+'<br>'+esc(r.email||'')+'</td><td>'+esc(r.booking_date||'—')+'<br>'+esc(r.booking_time||'—')+'</td><td>'+esc(r.guests??'—')+'</td><td>'+esc(tableName)+'</td><td><button type="button" class="booking-status booking-status-trigger '+esc(st)+'" data-booking-open data-name="'+esc(name)+'" data-phone="'+esc(r.phone||'')+'" data-email="'+esc(r.email||'')+'" data-date="'+esc(r.booking_date||'')+'" data-time="'+esc(r.booking_time||'')+'" data-guests="'+esc(r.guests??'')+'" data-code="'+esc(code)+'" data-status="'+esc(st)+'" data-table="'+esc(tableName)+'" data-notes="'+esc(r.notes||'')+'" aria-label="Open booking details for '+esc(name)+'">'+esc(st.toUpperCase())+'</button></td><td><div class="booking-row-actions"><button class="small-button" data-booking-message data-name="'+esc(name)+'" data-phone="'+esc(r.phone||'')+'" data-email="'+esc(r.email||'')+'" data-date="'+esc(r.booking_date||'')+'" data-time="'+esc(r.booking_time||'')+'" data-guests="'+esc(r.guests??'')+'" data-code="'+esc(code)+'" data-status="'+esc(st)+'">Message</button>'+(st==='pending'||st==='new'?'<button class="small-button" data-booking-status="confirmed" data-booking-id="'+esc(r.id)+'">Confirm</button><button class="small-button danger-button" data-booking-status="rejected" data-booking-id="'+esc(r.id)+'">Reject</button>':'')+'</div></td></tr>'}).join('')+'</tbody></table></div>'+(rows.length?'':'<div class="empty">No bookings found.</div>')+'<section class="booking-details-modal" id="bookingDetailsModal" hidden role="dialog" aria-modal="true" aria-labelledby="bookingDetailsTitle"><div class="booking-details-card"><div class="booking-details-heading"><div><p class="eyebrow">NABABI RISTORANTE</p><h3 id="bookingDetailsTitle">Booking details</h3></div><button class="secondary-button" type="button" data-booking-message-close aria-label="Close booking details">✕</button></div><dl class="booking-details-grid"><div><dt>Customer</dt><dd id="bookingDetailName">—</dd></div><div><dt>Booking code</dt><dd id="bookingDetailCode">—</dd></div><div><dt>Phone</dt><dd id="bookingDetailPhone">—</dd></div><div><dt>Email</dt><dd id="bookingDetailEmail">—</dd></div><div><dt>Date / time</dt><dd id="bookingDetailWhen">—</dd></div><div><dt>Guests</dt><dd id="bookingDetailGuests">—</dd></div><div><dt>Table</dt><dd id="bookingDetailTable">—</dd></div><div><dt>Status</dt><dd id="bookingDetailStatus">—</dd></div><div class="booking-detail-notes"><dt>Customer notes</dt><dd id="bookingDetailNotes">—</dd></div></dl><section class="booking-message-panel" id="bookingMessagePanel" hidden><h3>Send a message to customer</h3><p id="bookingMessageRecipient" class="booking-help"></p><label class="field">Message language<select id="bookingMessageLanguage"><option value="it">Italiano</option><option value="en">English</option><option value="bn">বাংলা</option></select></label><label class="field">Custom message<textarea id="bookingMessageText" rows="6" maxlength="2000"></textarea></label><div class="booking-row-actions"><button class="gold-button" type="button" data-booking-send-whatsapp>Open WhatsApp</button><button class="secondary-button" type="button" data-booking-send-email>Open Email</button><button class="secondary-button" type="button" data-booking-message-close>Close</button></div><p class="booking-help">মেসেজটি WhatsApp বা Email অ্যাপে তৈরি হবে। দেখে Send চাপুন; Admin থেকে স্বয়ংক্রিয়ভাবে পাঠানো হয় না।</p></section></div></section>';
}
async function setBookingStatusV2(id,status){if(!['confirmed','rejected'].includes(status))throw new Error('Invalid status');if(!confirm(status==='confirmed'?'এই বুকিংটি Confirm করবেন?':'এই বুকিংটি Reject করবেন?'))return;const r=await db.from('bookings').update({status}).eq('id',id).select('id').maybeSingle();if(r.error)throw r.error;if(!r.data)throw new Error('বুকিং আপডেট হয়নি। Supabase UPDATE permission পরীক্ষা করুন।');await recordStaffActivity('Updated','Booking status: '+status);await render('bookings')}
function filterBookingsV2(){const date=$('#bookingCalendarDate')?.value||'',filter=window.activeBookingFilterV2||'all';let n=0;document.querySelectorAll('#bookingCalendarRows tr').forEach(row=>{const st=String(row.dataset.bookingStatus||'pending').toLowerCase(),ok=(filter==='all'||(filter==='pending'?['pending','new'].includes(st):st===filter))&&(!date||row.dataset.bookingDate===date);row.hidden=!ok;if(ok)n++});const note=$('#bookingCalendarNote');if(note)note.textContent=n+' bookings shown.'}
function openBookingDetailsV2(b){const d=b.dataset,modal=$('#bookingDetailsModal'),set=(id,value)=>{const el=$(id);if(el)el.textContent=value||'—'};if(!modal)return;set('#bookingDetailName',d.name);set('#bookingDetailCode',d.code);set('#bookingDetailPhone',d.phone);set('#bookingDetailEmail',d.email);set('#bookingDetailWhen',[d.date,d.time].filter(Boolean).join(' '));set('#bookingDetailGuests',d.guests);set('#bookingDetailTable',d.table);set('#bookingDetailStatus',String(d.status||'pending').toUpperCase());set('#bookingDetailNotes',d.notes);openBookingMessageV2(b);modal.hidden=false;modal.scrollTop=0}
function openBookingMessageV2(b){const p=$('#bookingMessagePanel'),l=$('#bookingMessageLanguage');if(!p||!l)return;const d=b.dataset,n=d.name||'Customer',when=[d.date,d.time].filter(Boolean).join(' '),code=d.code||'—',guests=d.guests||'—',status=d.status||'pending';p.dataset.phone=d.phone||'';p.dataset.email=d.email||'';$('#bookingMessageRecipient').textContent=n+' · '+(d.email||d.phone||'Contact unavailable');const make=x=>x==='bn'?'প্রিয় '+n+', Nababi Ristorante-এ আপনার বুকিং ('+code+'), তারিখ ও সময়: '+when+', অতিথি: '+guests+'। বর্তমান অবস্থা: '+status+'। ধন্যবাদ।':x==='en'?'Dear '+n+', regarding your Nababi Ristorante booking ('+code+') for '+when+', '+guests+' guest(s): the current status is '+status+'. Thank you.':'Gentile '+n+', in merito alla sua prenotazione Nababi Ristorante ('+code+') del '+when+', per '+guests+' ospiti: lo stato attuale è '+status+'. Grazie.';$('#bookingMessageText').value=make(l.value);l.onchange=()=>$('#bookingMessageText').value=make(l.value);p.hidden=false}


async function homepageBackgroundPage(){
 if(role!=='admin')throw new Error('শুধু Super Admin হোমপেজের ব্যাকগ্রাউন্ড পরিবর্তন করতে পারবেন।');
 const r=await db.from('site_settings').select('setting_value').eq('setting_key','homepage_background_url').maybeSingle();
 if(r.error)throw r.error;
 const url=String(r.data?.setting_value||'');
 return '<section class="panel"><p class="eyebrow">PUBLIC WEBSITE</p><h2>Homepage Background</h2><p class="help">এখানে একটি JPG, PNG অথবা WebP ছবি আপলোড করুন। এই ছবিটি হোমপেজের বড় Hero অংশে ব্যাকগ্রাউন্ড হিসেবে দেখাবে। আগের তিনটি আলাদা খাবারের ছবি আর দেখানো হবে না। সর্বোচ্চ ১২ MB।</p>'+
 (url?'<div style="margin:14px 0"><img src="'+esc(url)+'" alt="Current homepage background" style="display:block;width:100%;max-width:620px;max-height:260px;object-fit:cover;border-radius:12px;border:1px solid #b99748"><p class="help">বর্তমানে ব্যবহৃত ব্যাকগ্রাউন্ড</p></div>':'<p class="help">এখনো কোনো ব্যাকগ্রাউন্ড আপলোড করা হয়নি। আপলোড না করা পর্যন্ত সবুজ ডিফল্ট ব্যাকগ্রাউন্ড থাকবে।</p>')+
 '<form id="homepageBackgroundForm" class="admin-form"><label for="homepageBackgroundFile">নতুন ব্যাকগ্রাউন্ড ছবি নির্বাচন করুন</label><input id="homepageBackgroundFile" name="background" type="file" accept="image/jpeg,image/png,image/webp" required><img id="homepageBackgroundPreview" alt="Selected background preview" hidden style="display:block;width:100%;max-width:620px;max-height:260px;object-fit:cover;border-radius:12px;margin-top:12px"><div class="form-actions"><button class="gold-button" type="submit">Upload & Save Background</button></div><p id="homepageBackgroundStatus" class="message" role="status" aria-live="polite"></p></form></section>';
}
async function saveHomepageBackground(e){
 e.preventDefault();
 if(role!=='admin')throw new Error('শুধু Super Admin এই কাজ করতে পারবেন।');
 const form=e.target,file=form.elements.background.files?.[0],status=$('#homepageBackgroundStatus'),button=form.querySelector('[type="submit"]');
 if(!file)throw new Error('আগে একটি ছবি নির্বাচন করুন।');
 button.disabled=true;status.textContent='ছবি আপলোড হচ্ছে…';
 try{
  const url=await uploadImage(file,'homepage',12*1024*1024);
  const saved=await db.from('site_settings').upsert({setting_key:'homepage_background_url',setting_value:url},{onConflict:'setting_key'});
  if(saved.error)throw saved.error;
  await recordStaffActivity('Updated','Homepage background image uploaded');
  await render('logo');
 }catch(error){status.textContent=error.message||'Upload failed.'}
 finally{button.disabled=false}
}

async function websiteSettingsPage(){
 if(role!=='admin')throw new Error('Admin only.');
 const r=await db.from('site_settings').select('setting_value').eq('setting_key','website_maintenance_mode').maybeSingle();
 if(r.error)throw r.error;
 const maintenance=String(r.data?.setting_value||'false').toLowerCase()==='true';
 return '<section class="panel"><p class="eyebrow">NABABI RISTORANTE</p><h2>'+t('websitePublic')+'</h2><p class="help">'+t('maintenanceHelp')+'</p><div class="website-status '+(maintenance?'is-maintenance':'is-public')+'"><strong>'+(maintenance?'🔴 '+t('publicOff'):'🟢 '+t('publicOn'))+'</strong></div><button id="websiteVisibilityToggle" class="'+(maintenance?'danger-button':'gold-button')+'" type="button" data-maintenance="'+String(maintenance)+'">'+(maintenance?t('publicOn'):t('publicOff'))+'</button><p id="websiteVisibilityStatus" class="message" aria-live="polite"></p></section>';
}
async function toggleWebsiteVisibility(button){
 if(role!=='admin')throw new Error('Admin only.');
 const next=button.dataset.maintenance!=='true';button.disabled=true;
 const r=await db.from('site_settings').upsert({setting_key:'website_maintenance_mode',setting_value:String(next)},{onConflict:'setting_key'});
 if(r.error)throw r.error;
 await recordStaffActivity('Updated','Website visibility: '+(next?'maintenance':'public'));
 await render('settings');
}
async function cameraManagementPage(){if(role!=='admin')throw new Error('Admin only.');const q=await db.from('cctv_cameras').select('camera_key,display_name,area,is_enabled,display_order').order('display_order');if(q.error)throw q.error;const cameras=q.data||[],selected=cameras.find(c=>c.camera_key===selectedCameraKey);const iconFor=k=>k==='kitchen'?'♨':k==='cash'?'▣':'◉';const list='<div class="camera-simple-list">'+cameras.map(c=>'<button type="button" class="camera-simple-card" data-camera-open="'+esc(c.camera_key)+'"><span class="camera-symbol">'+iconFor(c.camera_key)+'</span><span class="camera-simple-info"><b>'+esc(c.display_name)+'</b><small>'+esc(c.area)+'</small></span><span class="camera-simple-state '+(c.is_enabled?'is-enabled':'is-disabled')+'">'+(c.is_enabled?'চালু':'বন্ধ')+'</span><span class="camera-simple-arrow">›</span></button>').join('')+'</div>';const editor=selected?'<section class="camera-simple-editor"><div class="camera-editor-heading"><button type="button" class="secondary-button" data-camera-back>← সব ক্যামেরা</button><span class="status-pill status-pending">NVR সংযোগ বাকি</span></div><form class="camera-config-card" data-camera-config="'+esc(selected.camera_key)+'"><div class="camera-card-title"><span class="camera-symbol">'+iconFor(selected.camera_key)+'</span><div><h3>'+esc(selected.display_name)+'</h3><small>'+esc(selected.camera_key)+'</small></div></div><label class="field">ক্যামেরার নাম<input name="display_name" maxlength="80" required value="'+esc(selected.display_name)+'"></label><label class="field">কোন রুম / এলাকা<input name="area" maxlength="120" required value="'+esc(selected.area)+'"></label><label class="field">তালিকায় অবস্থান<input name="display_order" type="number" min="1" max="99" required value="'+Number(selected.display_order||1)+'"></label><label class="check-label"><input name="is_enabled" type="checkbox" '+(selected.is_enabled?'checked':'')+'> এই ক্যামেরা চালু রাখুন</label><div class="camera-config-actions"><button class="gold-button" type="submit">পরিবর্তন সংরক্ষণ করুন</button></div><p class="camera-save-status" aria-live="polite"></p></form></section>':'';return '<section class="panel"><div class="camera-page-head"><div><p class="eyebrow">NABABI · CCTV</p><h2>Camera Management</h2><p class="help">যে ক্যামেরার সেটিংস বদলাতে চান, শুধু সেই বক্সে চাপ দিন।</p></div><span class="status-pill status-pending">NVR not configured</span></div>'+ (selected?editor:list)+'</section>'+(!selected?'<section class="panel"><h2>সংযোগের অবস্থা</h2><p class="help">NVR হাতে এলে মডেল যাচাই করে নিরাপদভাবে ভিডিও সংযোগ করা হবে। এই পেজে কোনো NVR পাসওয়ার্ড বা ব্যক্তিগত ক্যামেরা URL রাখা হয় না।</p></section>':'');}
async function recordingCenterPage(){if(role!=='admin')throw new Error('Admin only.');const q=await db.from('cctv_cameras').select('camera_key,display_name,area,is_enabled').order('display_order');if(q.error)throw q.error;const cameras=q.data||[];const today=new Date().toLocaleDateString('en-CA');const icons={'dining-1':'🍽️','dining-2':'🍽️','cash':'🧾','kitchen':'👨‍🍳'};return '<section class="panel recording-center-panel"><div class="camera-page-head"><div><p class="eyebrow">NABABI · VIDEO ARCHIVE</p><h2>Recording Center</h2><p class="help">প্রথমে ক্যামেরা নির্বাচন করুন, তারপর তারিখ দিন। ভিডিও Hikvision NVR-এই থাকবে।</p></div><span class="status-pill status-pending">Playback unavailable</span></div><form id="recordingSearchForm" class="recording-simple-form"><h3 class="recording-step-title">১. কোন ক্যামেরার রেকর্ডিং দেখবেন?</h3><input type="hidden" name="camera_key" id="recordingCameraKey" required><div class="recording-camera-grid">'+cameras.map(c=>'<button type="button" class="recording-camera-card'+(c.is_enabled?'':' is-disabled')+'" data-recording-camera="'+esc(c.camera_key)+'" aria-pressed="false" '+(c.is_enabled?'':'disabled')+'><span class="recording-camera-icon">'+(icons[c.camera_key]||'📹')+'</span><span class="recording-camera-name">'+esc(c.display_name)+'</span><small>'+(c.is_enabled?'রেকর্ডিং ক্যামেরা':'Disabled')+'</small><span class="recording-camera-check" aria-hidden="true">✓</span></button>').join('')+'</div><div class="recording-date-block"><h3 class="recording-step-title">২. কোন তারিখের রেকর্ডিং?</h3><label class="field">তারিখ<input type="date" name="record_date" value="'+today+'" required></label></div><details class="recording-advanced"><summary>Advanced Search · নির্দিষ্ট সময় বা টেবিল</summary><div class="recording-advanced-fields"><label class="field">শুরুর সময়<input type="time" name="start_time"></label><label class="field">শেষ সময়<input type="time" name="end_time"></label><label class="field recording-zone-field">টেবিল / জোন (ঐচ্ছিক)<input type="text" name="zone" maxlength="80" placeholder="যেমন: Table 4 বা Kitchen entrance"></label></div></details><div class="recording-search-actions"><button class="gold-button" type="submit" disabled title="NVR model is required before searching">▶ রেকর্ডিং দেখুন</button><span class="status-pill status-pending">NVR সংযোগের অপেক্ষায়</span></div></form><div class="recording-empty-state"><span class="recording-play-icon">▶</span><h3>রেকর্ডিং চালানো এখনো প্রস্তুত নয়</h3><p>NVR-এর সঠিক মডেল ও নিরাপদ সংযোগ যাচাই হলে এখানে পাওয়া রেকর্ডিং দেখানো হবে।</p></div></section><section class="panel recording-privacy-panel"><h2>ভিডিও ও গোপনীয়তা</h2><div class="readiness-list"><span>✓ ভিডিও থাকবে Hikvision NVR হার্ডড্রাইভে</span><span>✓ ওয়েবসাইটে ভিডিও আপলোড হবে না</span><span>✓ NVR পাসওয়ার্ড সার্ভারেই সুরক্ষিত থাকবে</span></div></section>';}
